      noise_ceiling: input.noise_ceiling,
      broken_run_policy: {
        max_retries: brokenRunPolicy.max_retries,
        synthetic_scores: false,
      },
      stop_budget: {
        max_attempts: stopBudget.max_attempts,
        timeout_seconds: stopBudget.timeout_seconds,
      },
    },
